// Generated by vibelang from src/internal/FailureSummary.ts; the migrate flow writes it again with each batch.
/**
 * Bounded diagnostic headlines for durable agent failure records.
 * @since 1.0.0
 */
/**
 * The innermost typed sentence from the engine's JSON-safe failure value.
 * @category getters
 * @since 1.0.0
 */
export const failureSummary = (failure) => {
    let current = failure;
    let summary;
    for (let depth = 0; depth < 16 && typeof current === "object" && current !== null; depth++) {
        const row = current;
        if (typeof row["message"] === "string" && row["message"].trim() !== "") {
            const code = typeof row["code"] === "string" && row["code"] !== "" ? `${row["code"].slice(0, 128)}: ` : "";
            summary = `${code}${row["message"].replace(/\s+/g, " ").trim().slice(0, 1024)}`;
        }
        current = row["cause"];
    }
    return summary;
};
